@csrf_exempt
def api_employees(request):
    user = _api_auth(request)
    if not user:
        return JsonResponse({'error': 'Unauthorized'}, status=401)
    if user.role not in (User.ROLE_HR_ADMIN, User.ROLE_PAYROLL_SPECIALIST, User.ROLE_MANAGER):
        return JsonResponse({'error': 'Forbidden'}, status=403)
    qs = EmployeeProfile.objects.select_related('user', 'department').all()
    if user.role == User.ROLE_MANAGER:
        qs = qs.filter(Q(pk=user.profile.pk) | Q(manager=user.profile))
    data = []
    for emp in qs:
        data.append({
            'id': emp.pk,
            'employee_id': emp.employee_id,
            'name': emp.user.get_full_name(),
            'email': emp.user.email,
            'department': emp.department.name if emp.department else None,
            'job_title': emp.job_title,
            'status': emp.employment_status,
        })
    return JsonResponse({'employees': data})

@csrf_exempt
def api_employee_detail(request, pk):
    user = _api_auth(request)
    if not user:
        return JsonResponse({'error': 'Unauthorized'}, status=401)
    emp = get_object_or_404(EmployeeProfile.objects.select_related('user', 'department'), pk=pk)
    if user.role == User.ROLE_EMPLOYEE and emp.user != user:
        return JsonResponse({'error': 'Forbidden'}, status=403)
    if user.role == User.ROLE_MANAGER and emp.manager_id != user.profile.pk and emp.user != user:
        return JsonResponse({'error': 'Forbidden'}, status=403)
    log_action(user, AuditLog.ACTION_VIEW, emp, 'API view employee', request)
    return JsonResponse({
        'id': emp.pk,
        'employee_id': emp.employee_id,
        'name': emp.user.get_full_name(),
        'email': emp.user.email,
        'department': emp.department.name if emp.department else None,
        'job_title': emp.job_title,
        'status': emp.employment_status,
    })

@csrf_exempt
def api_compensation(request):
    user = _api_auth(request)
    if not user:
        return JsonResponse({'error': 'Unauthorized'}, status=401)
    if user.role not in (User.ROLE_HR_ADMIN, User.ROLE_PAYROLL_SPECIALIST):
        return JsonResponse({'error': 'Forbidden'}, status=403)
    recs = CompensationRecord.objects.select_related('employee__user').order_by('-effective_date')
    data = []
    for rec in recs:
        data.append({
            'employee_id': rec.employee.employee_id,
            'name': rec.employee.user.get_full_name(),
            'salary': str(rec.salary),
            'bonus': str(rec.bonus),
            'effective_date': str(rec.effective_date),
            'is_current': rec.is_current,
        })
    return JsonResponse({'compensation': data})

@csrf_exempt
def api_documents(request):
    user = _api_auth(request)
    if not user:
        return JsonResponse({'error': 'Unauthorized'}, status=401)
    if user.role not in (User.ROLE_HR_ADMIN, User.ROLE_PAYROLL_SPECIALIST):
        return JsonResponse({'error': 'Forbidden'}, status=403)
    docs = HRDocument.objects.select_related('employee__user').order_by('-created_at')
    data = []
    for doc in docs:
        data.append({
            'id': doc.pk,
            'title': doc.title,
            'category': doc.category,
            'employee_id': doc.employee.employee_id if doc.employee else None,
            'visible_to_employee': doc.visible_to_employee,
            'created_at': doc.created_at.isoformat(),
        })
    return JsonResponse({'documents': data})

